import sys
from collections import deque, defaultdict

def main():
    S = sys.stdin.read().strip()
    n = len(S)
    if n == 1:
        print(0)
        return

    graph = defaultdict(list)
    for i, digit in enumerate(S):
        graph[digit].append(i)

    visited = [False] * n
    queue = deque([(0, 0)])  # (index, jumps)
    visited[0] = True

    while queue:
        current_index, jumps = queue.popleft()
        if current_index == n - 1:
            print(jumps)
            return

        for next_index in [current_index - 1, current_index + 1]:
            if 0 <= next_index < n and not visited[next_index]:
                visited[next_index] = True
                queue.append((next_index, jumps + 1))

        for next_index in graph[S[current_index]]:
            if not visited[next_index]:
                visited[next_index] = True
                queue.extend([(next_index, jumps + 1)])

        graph[S[current_index]] = []  # Clear the list to avoid revisiting

if __name__ == "__main__":
    main()
